field.description:
Choose an XML file exported by Kontrol-ID. A valid import replaces the package sections and immediately applies the managed configuration.<br/>
<input class="form-control" type="file" id="kontrol_id_import_file" accept=".xml,text/xml,application/xml" />
<div id="kontrol_id_import_file_status" class="text-muted" style="margin-top:6px;">No file selected.</div>
<textarea name="kontrol_id_import_payload" id="kontrol_id_import_payload" style="display:none;"></textarea>
<button class="btn btn-success btn-sm" name="kontrol_id_import_settings" id="kontrol_id_import_settings" type="submit" value="kontrol_id_import_settings">
	<i class="fa fa-upload icon-embed-btn"></i>Import Kontrol-ID settings
</button>
<script type="text/javascript">
(function() {
	var fileInput = document.getElementById('kontrol_id_import_file');
	var payloadField = document.getElementById('kontrol_id_import_payload');
	var statusField = document.getElementById('kontrol_id_import_file_status');
	if (!fileInput || !payloadField || !statusField || typeof FileReader === 'undefined') {
		return;
	}
	fileInput.addEventListener('change', function() {
		if (!fileInput.files || fileInput.files.length === 0) {
			payloadField.value = '';
			statusField.className = 'text-muted';
			statusField.textContent = 'No file selected.';
			return;
		}
		var selectedFile = fileInput.files[0];
		var reader = new FileReader();
		reader.onload = function(event) {
			payloadField.value = event.target && event.target.result ? event.target.result : '';
			statusField.className = 'text-success';
			statusField.textContent = 'Selected file: ' + selectedFile.name;
		};
		reader.onerror = function() {
			payloadField.value = '';
			statusField.className = 'text-danger';
			statusField.textContent = 'Could not read the selected file.';
		};
		reader.readAsText(selectedFile);
	});
})();
</script>

packagegui.custom_php_validation_command:
/* Keep the generic package editor's write_config() audit entry explicit
 * even on platform versions that lose this parsed XML value during POST. */
$pkg['addedit_string'] = 'Kontrol-ID: changed settings.';
kontrol_id_validate($_POST, $input_errors);

packagegui.custom_php_resync_config_command:
kontrol_id_resync();
if (!empty($_POST['_kontrol_id_activation_deferred'])) {
	$savemsg = 'General settings were saved. Kontrol-ID remains disabled: ' .
		$_POST['_kontrol_id_activation_deferred'] .
		' Complete Domain and Keytab, then return to General to enable the service.';
}
unset($_POST['_kontrol_id_activation_deferred']);
